/**
 * Pins the onnxruntime-c pod to the version onnxruntime-react-native was built
 * for. Its podspec depends on "onnxruntime-c" with no version, so a fresh
 * `pod install` (every EAS build) takes the newest one, and the native engine
 * under the pet's voice could change with no change here.
 *
 * ios/ is generated by `expo prebuild`, so the pin lives in this plugin rather
 * than in the Podfile.
 */
const { withDangerousMod } = require('@expo/config-plugins');
const { mergeContents } = require('@expo/config-plugins/build/utils/generateCode');
const fs = require('fs');
const path = require('path');

const ORT_VERSION = require('onnxruntime-react-native/package.json').version;

module.exports = (config) =>
  withDangerousMod(config, [
    'ios',
    (config) => {
      const podfile = path.join(config.modRequest.platformProjectRoot, 'Podfile');
      const contents = fs.readFileSync(podfile, 'utf8');
      const merged = mergeContents({
        src: contents,
        newSrc: `  pod 'onnxruntime-c', '${ORT_VERSION}'`,
        tag: 'vitto-onnxruntime-pin',
        anchor: /use_expo_modules!/,
        offset: 1,
        comment: '#',
      });
      fs.writeFileSync(podfile, merged.contents);
      return config;
    },
  ]);
